const data = $('Webhook').first().json.body;
const history = data.history || [];

// Build a readable transcript
const transcript = history.map(h => {
  const speaker = h.role === 'assistant' ? 'Sophie' : 'Client';
  return `${speaker}: ${h.message}`;
}).join('\n');

return [{
  json: {
    telegram: data.telegram,
    latest_message: data.latest_message,
    transcript: transcript
  }
}];

